def maximumPoints(s, x, y):
    def remove(text, first, second, value):
        kept = []
        gained = 0
        for ch in text:
            if kept and kept[-1] == first and ch == second:
                kept.pop()
                gained += value
            else:
                kept.append(ch)
        return kept, gained

    if x >= y:
        rest, g1 = remove(s, 'a', 'b', x)
        _, g2 = remove(rest, 'b', 'a', y)
    else:
        rest, g1 = remove(s, 'b', 'a', y)
        _, g2 = remove(rest, 'a', 'b', x)
    return g1 + g2
